  { case_id: 'CASE 9', phone: '+1234567890123456', expected_phone: 'INVALID', expected_country_prefix: null, expected_normalized_phone: null },
];

return cases.map((testCase, index) => {
  const source = {
    body: {
      data: {
        appointment: {
          uuid: 'synthetic-appointment-' + String(index + 1).padStart(2, '0'),
          start: '2026-01-01T00:00:00Z',
          customer: {
            uuid: 'synthetic-customer-' + String(index + 1).padStart(2, '0'),
            email: 'synthetic.customer.' + String(index + 1).padStart(2, '0') + '@example.test',
            phone: testCase.phone,
          },
        },
      },
    },
  };

  return {
    json: {
      case_id: testCase.case_id,
      expected_phone: testCase.expected_phone,
      expected_country_prefix: testCase.expected_country_prefix,
      expected_normalized_phone: testCase.expected_normalized_phone,
      event_type: 'appointment.booking.created',
      event_created: '2026-01-01T00:00:00',
      appointment_uuid: source.body.data.appointment.uuid,
      appointment_start_utc: source.body.data.appointment.start,
