const failures = [];

if (items.length !== 9) {
  throw new Error('Phone enhancement test expected exactly 9 cases but received ' + items.length);
}

for (const item of items) {
  const data = item.json;
  const identifiers = data.sanitized_payload.userIdentifiers;
  const phoneIdentifier = identifiers.find((identifier) => Object.prototype.hasOwnProperty.call(identifier, 'hashedPhoneNumber'));
  const emailIdentifier = identifiers.find((identifier) => Object.prototype.hasOwnProperty.call(identifier, 'hashedEmail'));
  const expectPhonePresent = data.expected_phone === 'VALID_E164';
  const checks = data.checks;
  const expectedPhoneHash = data.expected_normalized_phone ? sha256(data.expected_normalized_phone) : null;

  const assertions = [
    ['email identifier present', Boolean(emailIdentifier) && checks.hashed_email_present],
    ['raw phone absent', checks.raw_phone_present === false],
    ['normalized phone absent', checks.normalized_phone_present === false],
    ['phone identifier expected presence', Boolean(phoneIdentifier) === expectPhonePresent],
    ['hashed phone presence flag', checks.hashed_phone_present === expectPhonePresent],
    ['hashed phone hex sha256', checks.hashed_phone_is_hex_sha256 === true],
    ['email and phone identifiers separate', checks.email_and_phone_are_separate === true],
    ['phone hash matches expected normalized value', expectPhonePresent ? phoneIdentifier?.hashedPhoneNumber === expectedPhoneHash : !phoneIdentifier],
  ];

  for (const [assertion, passed] of assertions) {
    if (!passed) {
      failures.push({ case_id: data.case_id, assertion });
    }
  }
}

if (failures.length > 0) {
  throw new Error('Phone enhancement test failed: ' + JSON.stringify(failures));
}

return [
  {
    json: {
      total_cases: items.length,
      passed: items.length,
      failed: 0,
      status: 'PASS',
    },
  },
];
